// Define all categories to scrape - UPDATED URLs (site changed from /post/category/ to /category/)
const categories = [
  { name: 'AI Applications', url: 'https://nuvemmag.com/category/yapay-zeka-uygulamalari', tag: 'AI Applications' },
  { name: 'Latest News', url: 'https://nuvemmag.com/category/en-son-haberler', tag: 'Latest News' },
  { name: 'Artificial Intelligence', url: 'https://nuvemmag.com/category/yapay-zeka', tag: 'AI' },
  { name: 'Technology', url: 'https://nuvemmag.com/category/teknoloji', tag: 'Tech' },
  { name: 'Sustainability', url: 'https://nuvemmag.com/category/surdurulebilirlik', tag: 'Sustainability' },
  { name: 'Science & World', url: 'https://nuvemmag.com/category/bilim-ve-dunya', tag: 'Science' },
  { name: 'Agenda', url: 'https://nuvemmag.com/category/gundem', tag: 'News' },
];

// Return each category as a separate item
return categories.map(cat => ({
  json: {
    categoryName: cat.tag,
    categoryFullName: cat.name,
    newsSourceUrl: cat.url,
    supabaseTableName: 'tech_news_articles'
  }
}));

// Handle Firecrawl API response format for scrape operation
const input = $input.item.json;

// Get category info from Loop Over Categories
let categoryInfo = {};
try {
  categoryInfo = $('Loop Over Categories').item.json || {};
} catch (e) {
  console.log('Could not get category info from Loop:', e.message);
  categoryInfo = $input.item.json || {};
}

// DEBUG: Log what we received from Firecrawl
console.log('🔥 Firecrawl raw response keys:', Object.keys(input));
console.log('🔥 Has data?', !!input.data);
console.log('🔥 Has markdown?', !!input.markdown);
if (input.data) {
  console.log('🔥 Data keys:', Object.keys(input.data));
}

// Firecrawl scrape operation can return data in different formats:
// 1. { data: { markdown: "..." } } - standard scrape response
// 2. { markdown: "..." } - direct markdown
// 3. { success: true, data: { markdown: "..." } }
let markdown = '';

if (input.data && input.data.markdown) {
  markdown = input.data.markdown;
  console.log('✅ Found markdown in input.data.markdown');
} else if (input.markdown) {
  markdown = input.markdown;
  console.log('✅ Found markdown in input.markdown');
} else if (input.data && input.data.content) {
  markdown = input.data.content;
  console.log('✅ Found content in input.data.content');
} else if (input.content) {
  markdown = input.content;
  console.log('✅ Found content in input.content');
} else {
  // Last resort: try to stringify and check
  console.log('❌ No markdown found! Raw input:', JSON.stringify(input).substring(0, 500));
}

console.log('📊 Category:', categoryInfo.categoryName || 'unknown');
console.log('📊 Markdown length:', markdown.length);

if (markdown.length === 0) {
  console.log('⚠️ WARNING: Empty markdown! Check Firecrawl node configuration.');
}

return {
  json: {
    markdown: markdown || '',
    categoryName: categoryInfo.categoryName || '',
    categoryFullName: categoryInfo.categoryFullName || '',
    newsSourceUrl: categoryInfo.newsSourceUrl || '',
    supabaseTableName: categoryInfo.supabaseTableName || 'tech_news_articles'
  }
};

// Parse the AI output and return individual articles
const output = $input.item.json.output;
let articles = [];

// Get category info passed through
const prevData = $('Normalize Firecrawl Output').item.json;
const categoryName = prevData.categoryName;
const supabaseTableName = prevData.supabaseTableName;

try {
  if (typeof output === 'string') {
    const parsed = JSON.parse(output);
    articles = parsed.articles || parsed || [];
  } else if (output && output.articles) {
    articles = output.articles;
  } else if (Array.isArray(output)) {
    articles = output;
  }
} catch (e) {
  console.log('Parse error:', e.message);
  return [{ json: { noArticles: true, categoryName: categoryName, supabaseTableName: supabaseTableName } }];
}

console.log('Found', articles.length, 'articles in category:', categoryName);

// Filter out invalid articles - must have title, url, and date
const validArticles = articles.filter(article => {
  const hasTitle = article.title && article.title.trim() !== '';
  const hasUrl = article.url && article.url.trim() !== '';
  const hasDate = article.date && article.date.trim() !== '';
  return hasTitle && hasUrl && hasDate;
});

const filteredCount = articles.length - validArticles.length;
if (filteredCount > 0) {
  console.log('Filtered out', filteredCount, 'invalid articles (missing title, url, or date)');
}
console.log('Valid articles:', validArticles.length);

// If no valid articles found, return a single item with noArticles flag
if (validArticles.length === 0) {
  console.log('No valid articles found, returning noArticles flag');
  return [{ json: { noArticles: true, categoryName: categoryName, supabaseTableName: supabaseTableName } }];
}

// Return each valid article as a separate item for looping
// AI Agent already filters by date, so we return all valid articles
return validArticles.map(article => ({
  json: {
    title: article.title || '',
    url: article.url || '',
    date: article.date || '',
    categoryName: categoryName,
    supabaseTableName: supabaseTableName
  }
}));

// No articles found in this category, continue to next category
const categoryName = $('Normalize Firecrawl Output').item.json.categoryName;
console.log('No articles found in category:', categoryName);
return [{ json: { message: 'No articles in ' + categoryName } }];

// Prepare article data and extract slug for robust duplicate check
const article = $input.item.json;

// Normalize URL
let url = article.url || '';
url = url.replace(/\/$/, ''); // Remove trailing slash

// Extract slug from URL for pattern matching
// URL can be: https://nuvemmag.com/article-slug or https://nuvemmag.com/post/article-slug
let slug = '';
try {
  const urlObj = new URL(url);
  const path = urlObj.pathname;
  // Remove /post/ prefix if present, then get the slug
  slug = path.replace(/^\/post\//, '/').replace(/^\//, '').replace(/\/$/, '');
} catch (e) {
  slug = url.split('/').pop() || '';
}

console.log('🔍 Checking:', article.title?.substring(0, 50));
console.log('🔗 URL:', url);
console.log('🏷️ Slug:', slug);

return {
  json: {
    articleTitle: article.title || '',
    articleUrl: url,
    articleDate: article.date || '',
    categoryName: article.categoryName || '',
    supabaseTableName: article.supabaseTableName || 'tech_news_articles',
    url: url,
    slug: slug
  }
};

// Check if article exists in database using slug-based matching
const dbResult = $input.item.json || {};
const preparedData = $('Prepare DB Check').item.json;

const title = preparedData.articleTitle || '';
const url = preparedData.articleUrl || '';
const slug = preparedData.slug || '';
const date = preparedData.articleDate || '';
const categoryName = preparedData.categoryName || '';
const supabaseTableName = preparedData.supabaseTableName || 'tech_news_articles';

// Check if article exists in DB
const hasDbId = dbResult && dbResult.id;
const matchedUrl = dbResult.source_url || '';
const articleExists = hasDbId ? true : false;

// Clear logging
console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
console.log('📰', title.substring(0, 60));
console.log('🔍 Slug:', slug);
if (articleExists) {
  console.log('⏭️ SKIP - Already in DB');
  console.log('   DB URL:', matchedUrl);
} else {
  console.log('✅ NEW - Will process');
}
console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

return [{
  json: {
    title: title,
    url: url,
    date: date,
    categoryName: categoryName,
    supabaseTableName: supabaseTableName,
    isNew: !articleExists,
    dbId: dbResult.id || null,
    existsInDb: articleExists
  }
}];

// Extract date, metadata, and find tweet IDs from HTML
const articleData = $('Is New Article?').item.json;
const articleUrl = articleData.url || '';
const turkishDate = articleData.date || '';
const originalTitle = articleData.title || '';
const categoryName = articleData.categoryName || '';
const supabaseTableName = articleData.supabaseTableName || 'tech_news_articles';

// Normalize Firecrawl output
const input = $input.item.json;
let markdown = input.data?.markdown || input.markdown || '';
let rawHtml = input.data?.rawHtml || input.rawHtml || input.data?.html || input.html || '';

console.log('📝 Markdown length:', markdown.length);
console.log('📄 HTML length:', rawHtml.length);
console.log('🔗 Article URL:', articleUrl);

// Extract tweet IDs from HTML
let extractedTweetIds = [];
if (rawHtml) {
  // Pattern 1: twitter.com/*/status/ID or x.com/*/status/ID
  const statusMatches = rawHtml.matchAll(/(?:twitter\.com|x\.com)\/[\w]+\/status\/(\d{15,20})/gi);
  for (const m of statusMatches) {
    if (!extractedTweetIds.includes(m[1])) extractedTweetIds.push(m[1]);
  }
  // Pattern 2: data-tweet-id="ID"
  const dataMatches = rawHtml.matchAll(/data-tweet-id=["'](\d{15,20})["']/gi);
  for (const m of dataMatches) {
    if (!extractedTweetIds.includes(m[1])) extractedTweetIds.push(m[1]);
  }
}
console.log('🐦 Found tweet IDs:', extractedTweetIds);

// Extract YouTube IDs from HTML
let extractedYoutubeIds = [];
if (rawHtml) {
  const ytMatches = rawHtml.matchAll(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([\w-]{11})/gi);
  for (const m of ytMatches) {
    if (!extractedYoutubeIds.includes(m[1])) extractedYoutubeIds.push(m[1]);
  }
}
console.log('📺 Found YouTube IDs:', extractedYoutubeIds);

// Turkish month mapping
const turkishMonths = {
  'ocak': '01', 'şubat': '02', 'mart': '03', 'nisan': '04',
  'mayıs': '05', 'haziran': '06', 'temmuz': '07', 'ağustos': '08',
  'eylül': '09', 'ekim': '10', 'kasım': '11', 'aralık': '12'
};

// Parse date
const now = new Date();
let isoDate = now.toISOString().split('T')[0];
try {
  const absMatch = turkishDate.match(/(\d{1,2})\s+([a-zA-ZğüşıöçĞÜŞİÖÇ]+)\s+(\d{4})/i);
  if (absMatch) {
    const day = absMatch[1].padStart(2, '0');
    const month = turkishMonths[absMatch[2].toLowerCase()] || '01';
    isoDate = `${absMatch[3]}-${month}-${day}`;
    console.log('✅ Absolute date:', isoDate);
  } else {
    const relMatch = turkishDate.match(/(\d+)\s+(saat|gün|dakika|hafta|ay)\s+önce/i);
    if (relMatch) {
      const amount = parseInt(relMatch[1]);
      const unit = relMatch[2].toLowerCase();
      const date = new Date(now);
      if (unit === 'dakika') date.setMinutes(date.getMinutes() - amount);
      else if (unit === 'saat') date.setHours(date.getHours() - amount);
      else if (unit === 'gün') date.setDate(date.getDate() - amount);
      else if (unit === 'hafta') date.setDate(date.getDate() - (amount * 7));
      else if (unit === 'ay') date.setMonth(date.getMonth() - amount);
      isoDate = date.toISOString().split('T')[0];
      console.log('✅ Relative date:', turkishDate, '->', isoDate);
    }
  }
} catch (e) { console.log('Date error:', e.message); }

return {
  json: {
    sourceUrl: articleUrl,
    turkishDate: turkishDate,
    isoDate: isoDate,
    originalTitle: originalTitle,
    categoryName: categoryName,
    supabaseTableName: supabaseTableName,
    markdown: markdown || '',
    extractedTweetIds: extractedTweetIds,
    extractedYoutubeIds: extractedYoutubeIds
  }
};

