// Generate slug from English title
const englishTitle = $('Translator Agent - Turkish to English').item.json.output.title || '';

const slug = englishTitle
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 100);

console.log('📝 Generated slug:', slug);

return {
  json: {
    slug: slug
  }
};

// Check if publish was successful or failed (duplicate)
const result = $input.item.json;
const error = $input.item.error;

if (error) {
  // Check if it's a duplicate error
  const errorMsg = error.message || JSON.stringify(error);
  if (errorMsg.includes('duplicate') || errorMsg.includes('unique constraint')) {
    console.log('⚠️ Duplicate article skipped (already in DB)');
    return [{ json: { success: false, reason: 'duplicate', skipped: true } }];
  }
  console.log('❌ Publish error:', errorMsg);
  return [{ json: { success: false, reason: 'error', error: errorMsg } }];
}

console.log('✅ Article published successfully!');
return [{ json: { success: true, published: true, id: result.id } }];

